        IF EXISTS
        (
            SELECT 1
            FROM [dbo].[Cities]
            WHERE [Boundary] IS NULL
               OR [Boundary].STSrid <> 4326
               OR [Boundary].STIsValid() <> 1
        )
            THROW 50003, N'اعتبارسنجی نهایی محدوده شهرها ناموفق بود.', 1;

