BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO

SELECT
    s.[Id] AS [StateId],
    s.[Name] AS [StateName],
    COUNT(c.[Id]) AS [CityCount],
    SUM(CASE WHEN c.[Boundary] IS NOT NULL THEN 1 ELSE 0 END) AS [CityBoundaryCount]
FROM [dbo].[States] AS s
LEFT JOIN [dbo].[Cities] AS c
    ON c.[StateId] = s.[Id]
GROUP BY s.[Id], s.[Name]
ORDER BY s.[Id];
GO
